import { createHash } from 'node:crypto';
import type { Readable } from 'node:stream';

export type StoredObject = { sizeBytes: number; sha256: string; head: Buffer };

export class ObjectTooLargeError extends Error {}

/**
 * Where document bytes live (spec §10). Keys are generated by DocumentsService (`facility/<id>/<documentId>`) and
 * never reach clients; every driver keeps objects private and is only read back through the API's signed links.
 */
export interface StorageDriver {
  /** Stores at most `maxBytes`; rejects with ObjectTooLargeError past that and leaves nothing behind. */
  write(key: string, source: Readable, maxBytes: number): Promise<StoredObject>;
  read(key: string): Promise<Readable>;
  exists(key: string): Promise<boolean>;
  remove(key: string): Promise<void>;
}

/** Lower-case segments separated by `/`: what DocumentsService generates, and nothing that could escape a prefix. */
export function assertStorageKey(key: string) {
  if (!/^[a-z0-9-]+(\/[a-z0-9-]+)*$/.test(key)) throw new Error('Invalid storage key');
}

/**
 * Reads a stream into memory, hashing and counting as it goes and stopping past `maxBytes`. Remote drivers use it
 * so size and content checks happen before anything is sent; documents are capped at 10 MB, so buffering is fine.
 */
export async function readCapped(source: Readable, maxBytes: number): Promise<StoredObject & { body: Buffer }> {
  const hash = createHash('sha256');
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of source) {
    const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk as Uint8Array);
    size += buffer.length;
    if (size > maxBytes) {
      source.destroy();
      throw new ObjectTooLargeError();
    }
    hash.update(buffer);
    chunks.push(buffer);
  }
  const body = Buffer.concat(chunks, size);
  return { body, sizeBytes: size, sha256: hash.digest('hex'), head: body.subarray(0, 16) };
}
